def count_islands_with_total_value_divisible_by_k(grid, k):
    # Edge case: empty grid
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])
    visited = [[False] * n for _ in range(m)]

    def dfs(r, c):
        # Iterative flood fill (avoids recursion limits for large islands); returns the island sum
        visited[r][c] = True
        stack = [(r, c)]
        total = 0
        while stack:
            x, y = stack.pop()
            total += grid[x][y]
            for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] > 0 and not visited[nx][ny]:
                    visited[nx][ny] = True
                    stack.append((nx, ny))
        return total

    count = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] > 0 and not visited[i][j]:
                island_sum = dfs(i, j)
                if island_sum % k == 0:
                    count += 1
    return count
